import Foundation
import NIO
import NIOHTTP1

// MARK: - Payment Processing Service with Rate Limiting

struct PaymentRequest: Codable {
    let merchantId: String
    let amount: Decimal
    let currency: String
    let idempotencyKey: String
}

struct PaymentResponse: Codable {
    let transactionId: String
    let status: String
    let timestamp: Date
}

class RateLimiter {
    private var tokens: [String: (count: Int, resetTime: Date)] = [:]
    private let maxRequests: Int = 100
    private let windowSeconds: TimeInterval = 60
    private let lock = NSLock()

    func allowRequest(for clientId: String) -> Bool {
        lock.lock()
        defer { lock.unlock() }

        let now = Date()
        if let bucket = tokens[clientId] {
            if now >= bucket.resetTime {
                tokens[clientId] = (count: 1, resetTime: now.addingTimeInterval(windowSeconds))
                return true
            }
            if bucket.count >= maxRequests {
                return false
            }
            tokens[clientId] = (count: bucket.count + 1, resetTime: bucket.resetTime)
            return true
        }
        tokens[clientId] = (count: 1, resetTime: now.addingTimeInterval(windowSeconds))
        return true
    }
}

// MARK: - Retry Queue with Persistent State

class RetryQueue {
    private let storageDirectory: URL
    private let maxRetries: Int = 3

    init(storageDirectory: URL) {
        self.storageDirectory = storageDirectory
        try? FileManager.default.createDirectory(at: storageDirectory, withIntermediateDirectories: true)
    }

    func enqueueForRetry(payload: Data, attemptCount: Int, metadata: [String: String]) throws {
        let entry = RetryEntry(payload: payload, attemptCount: attemptCount, metadata: metadata)
        let encoded = try NSKeyedArchiver.archivedData(withRootObject: entry, requiringSecureCoding: false)
        let filename = UUID().uuidString + ".retry"
        let fileURL = storageDirectory.appendingPathComponent(filename)
        try encoded.write(to: fileURL)
    }

    func processRetryQueue() throws -> [RetryEntry] {
        let files = try FileManager.default.contentsOfDirectory(at: storageDirectory, includingPropertiesForKeys: nil)
        var entries: [RetryEntry] = []

        for file in files where file.pathExtension == "retry" {
            let data = try Data(contentsOf: file)
            // Restore retry entries from persistent storage
            if let entry = try NSKeyedUnarchiver.unarchiveTopLevelObjectWithData(data) as? RetryEntry {
                if entry.attemptCount < maxRetries {
                    entries.append(entry)
                }
                try FileManager.default.removeItem(at: file)
            }
        }
        return entries
    }
}

class RetryEntry: NSObject, NSCoding {
    let payload: Data
    let attemptCount: Int
    let metadata: [String: String]

    init(payload: Data, attemptCount: Int, metadata: [String: String]) {
        self.payload = payload
        self.attemptCount = attemptCount
        self.metadata = metadata
    }

    required init?(coder: NSCoder) {
        self.payload = coder.decodeObject(forKey: "payload") as? Data ?? Data()
        self.attemptCount = coder.decodeInteger(forKey: "attemptCount")
        self.metadata = coder.decodeObject(forKey: "metadata") as? [String: String] ?? [:]
    }

    func encode(with coder: NSCoder) {
        coder.encode(payload, forKey: "payload")
        coder.encode(attemptCount, forKey: "attemptCount")
        coder.encode(metadata, forKey: "metadata")
    }
}

// MARK: - Payment Processor

class PaymentProcessor {
    private let rateLimiter = RateLimiter()
    private let retryQueue: RetryQueue
    private let hmacKey: Data

    init(storageDir: URL, hmacKey: Data) {
        self.retryQueue = RetryQueue(storageDirectory: storageDir)
        self.hmacKey = hmacKey
    }

    func handlePayment(requestData: Data, clientId: String, signature: String) throws -> PaymentResponse {
        // Rate limiting check
        guard rateLimiter.allowRequest(for: clientId) else {
            throw PaymentError.rateLimited
        }

        // Verify HMAC signature
        guard verifySignature(data: requestData, signature: signature, key: hmacKey) else {
            throw PaymentError.invalidSignature
        }

        // Decode payment request using Codable (safe)
        let decoder = JSONDecoder()
        let request = try decoder.decode(PaymentRequest.self, from: requestData)

        // Validate payment parameters
        guard request.amount > 0 && request.amount <= 50000 else {
            throw PaymentError.invalidAmount
        }

        guard ["USD", "EUR", "GBP"].contains(request.currency) else {
            throw PaymentError.unsupportedCurrency
        }

        // Process payment (simulated)
        let result = processWithGateway(request: request)

        if case .failure = result {
            // Queue for retry on transient failures
            try retryQueue.enqueueForRetry(
                payload: requestData,
                attemptCount: 1,
                metadata: ["clientId": clientId, "sig": signature]
            )
        }

        return PaymentResponse(
            transactionId: UUID().uuidString,
            status: "processed",
            timestamp: Date()
        )
    }

    func processRetries() throws {
        let entries = try retryQueue.processRetryQueue()
        for entry in entries {
            if let clientId = entry.metadata["clientId"],
               let sig = entry.metadata["sig"] {
                _ = try? handlePayment(requestData: entry.payload, clientId: clientId, signature: sig)
            }
        }
    }

    private func processWithGateway(request: PaymentRequest) -> Result<String, Error> {
        // Simulated gateway call
        return .success("txn_\(UUID().uuidString)")
    }

    private func verifySignature(data: Data, signature: String, key: Data) -> Bool {
        // HMAC-SHA256 verification
        let computed = computeHMAC(data: data, key: key)
        return computed == signature
    }

    private func computeHMAC(data: Data, key: Data) -> String {
        var hmac = [UInt8](repeating: 0, count: 32)
        data.withUnsafeBytes { dataPtr in
            key.withUnsafeBytes { keyPtr in
                CCHmac(CCHmacAlgorithm(kCCHmacAlgSHA256), keyPtr.baseAddress, key.count, dataPtr.baseAddress, data.count, &hmac)
            }
        }
        return Data(hmac).base64EncodedString()
    }
}

enum PaymentError: Error {
    case rateLimited
    case invalidSignature
    case invalidAmount
    case unsupportedCurrency
    case gatewayError
}
